void SystemEdukacyjny::attachPrzedmiot(Przedmiot* p) {
    przedmioty.push_back(p);
}

void SystemEdukacyjny::detachPrzedmiot(string n) {
    vector<Przedmiot*>::iterator it;

    Przedmiot* foundPrzedmiot = nullptr;

    for (it = przedmioty.begin(); it != przedmioty.end(); it++){
        if ((*it)->getNazwa() == n){
            foundPrzedmiot = (*it);

            przedmioty.erase(it);
            break;
        }
    }

    if (foundPrzedmiot == nullptr){
        cout << "Nie znaleziono przedmiotu " << n << " w systemie\n";
    }
}

Przedmiot* SystemEdukacyjny::getPrzedmiot(string n) {
     vector<Przedmiot*>::iterator it;

    Przedmiot* foundPrzedmiot = nullptr;

    for (it = przedmioty.begin(); it != przedmioty.end(); it++){
        if ((*it)->getNazwa() == n){
            foundPrzedmiot = (*it);
            break;
        }
    }

    return foundPrzedmiot;
}

bool SystemEdukacyjny::sprawdzCzyUzytkownikIstnieje(string l) {
    vector<Konto*>::iterator it;

    for (it = konta.begin(); it != konta.end(); it++){
        if ((*it)->getLogin() == l){
            return true;
        }
    }

    return false;
}

Konto* SystemEdukacyjny::getKonto(string l) {
    vector<Konto*>::iterator it;

    Konto* foundKonto = nullptr;

    for (it = konta.begin(); it != konta.end(); it++){
        if ((*it)->getLogin() == l){
            foundKonto = (*it);
            break;
        }
    }

    return foundKonto;
}

