void SystemEdukacyjny::wczytajPrzedmiotyIKontaZPliku(string nazwaPliku, string nazwaPlikuPrzemiotow) {
    ifstream file;

    file.open(nazwaPliku, ios::in);

    string line = "";
    string word = "";

    while (getline(file, line)){
        stringstream s(line);
        int counter = 0;

        string accountType = "";
        string loginFromCsv = "";
        string passwordFromCsv = "";
        string preLastColumn = "";
        string lastColumn = "";

        while (getline(s, word, ',')){
            counter++;
            if (counter == 1){
                accountType = word;
            }

            else if (counter == 2){
                loginFromCsv = word;
            }

            else if (counter == 3){
                passwordFromCsv = word;
            }

            else if (counter == 4){
                preLastColumn = word;
            }
            else if (counter == 5){
                lastColumn = word;
            }
        }
            if (accountType == "Student"){
                Student* studentToAdd = new Student(loginFromCsv, passwordFromCsv, preLastColumn, lastColumn);
                studentToAdd->setIndeksStudenta(lastColumn);

                attachKonto(studentToAdd);
            }
            else if (accountType == "Wykladowca"){
                Wykladowca* teacherToAdd = new Wykladowca(loginFromCsv, passwordFromCsv, lastColumn);
                teacherToAdd->setIndeksWykladowcy(lastColumn);

                teacherToAdd->setLicznikMaterialowDoWeryfikacji(stoi(preLastColumn));
                attachKonto(teacherToAdd);
            }
            else if (accountType == "Admin"){
                Admin* adminToAdd = new Admin(loginFromCsv, passwordFromCsv);

                adminToAdd->setLicznikMaterialowDoDodania(stoi(preLastColumn));
                attachKonto(adminToAdd);
            }

        }
        file.close();

        ifstream subjectFile;

        subjectFile.open(nazwaPlikuPrzemiotow, ios::in);

        vector<string> subjectRow;
        string subjectLine = "";
        string subjectWord = "";


    while (getline(subjectFile, subjectLine)){
        stringstream sSubjet(subjectLine);

        string subjectName = "";
        string subjectDescription = "";
        string subjectContact = "";
        string subjectGroup = "";

        vector<Wykladowca*> teachersToAdd;
        string currentName = "";

        vector<Student*> studentsToAdd;
        string currentStuddentName = "";

        vector<Material*> materialsToAdd;

        string teacherString = "";
        string studentString = "";

        bool teachersStarted = false;
        bool studentsStarted = false;
        bool materialsStarted = false;

        string materialTitle = "";
        string materialAttachment = "";
        bool isByTeacher = false;
        bool isVerified = false;
        bool isAddedByAdmin = false;


        int subjectCounter = 0;
        int materialCounter = 0;

        while(getline(sSubjet, subjectWord, ',')){
            subjectCounter++;

            if (subjectCounter == 1){
                subjectName = subjectWord;
            }
            else if (subjectCounter == 2){
                subjectDescription = subjectWord;
            }
            else if (subjectCounter == 3){
                subjectContact = subjectWord;
            }
            else if (subjectCounter == 4){
                subjectGroup = subjectWord;
            }
            else {
                if (subjectWord == "WYKLADOWCY"){
                    teachersStarted = true;
                    studentsStarted = false;
                    materialsStarted = false;
                    continue;
                }

                if (subjectWord == "STUDENCI"){
                    teachersStarted = false;
                    studentsStarted = true;
                    materialsStarted = false;
                    continue;
                }

                if (subjectWord == "MATERIALY"){
                    teachersStarted = false;
                    studentsStarted = false;
                    materialsStarted = true;
                    continue;
                }

                if (teachersStarted && subjectWord != "brak"){
                    teacherString = subjectWord;

                    Wykladowca* teacherToAdd = dynamic_cast<Wykladowca*> (getKonto(teacherString));
                    if (teacherToAdd != nullptr){
                        teachersToAdd.push_back(teacherToAdd);
                    }
                }

                else if (studentsStarted && subjectWord != "brak"){
                    studentString = subjectWord;

                    Student* studentToAdd = dynamic_cast<Student*> (getKonto(studentString));
                    if (studentToAdd != nullptr){
                        studentsToAdd.push_back(studentToAdd);
                    }
                }

                else if (materialsStarted && subjectWord != "brak"){
                    materialCounter++;

                    if (materialCounter == 1){
                        materialTitle = subjectWord;
                    }
                    else if (materialCounter == 2){
                        materialAttachment = subjectWord;
                    }
                    else if (materialCounter == 3){
                        if (subjectWord == "true"){
                            isByTeacher = true;
                        }
                        else {
                            isByTeacher = false;
                        }
                    }
                    else if (materialCounter == 4){
                        if (subjectWord == "true"){
                            isVerified = true;
                        }
                        else {
                            isVerified = false;
                        }
                    }
                    else if (materialCounter == 5){
                        if (subjectWord == "true"){
                            isAddedByAdmin = true;
                        }
                        else{
                            isAddedByAdmin = false;
                        }

                        Material* materialToAdd = new Material(materialTitle, materialAttachment, isByTeacher);
                        materialToAdd->setCzyJestZweryfikowany(isVerified);
                        materialToAdd->setCzyJestDodanyPrzezAdmina(isAddedByAdmin);;

                        materialsToAdd.push_back(materialToAdd);

                        materialCounter = 0;
                    }
                }
            }
        }


    Przedmiot* subjectToAdd = new Przedmiot(subjectName, subjectDescription, subjectContact, subjectGroup);

    vector<Wykladowca*>::iterator wIt;

    for (wIt = teachersToAdd.begin(); wIt != teachersToAdd.end(); wIt++){
        subjectToAdd->attachWykladowca((*wIt));
    }

    vector<Student*>::iterator sIt;

    for (sIt = studentsToAdd.begin(); sIt != studentsToAdd.end(); sIt++){
        subjectToAdd->attachStudent((*sIt));
    }

    vector<Material*>::iterator mIt;

    for (mIt = materialsToAdd.begin(); mIt != materialsToAdd.end(); mIt++){
        subjectToAdd->attachMaterial((*mIt));
    }

    attachPrzedmiot(subjectToAdd);

    }

    subjectFile.close();
}


void SystemEdukacyjny::zapiszPrzedmiotyIKontaDoPliku(string nazwaPliku, string nazwaPlikuPrzedmiotow) {
    vector<Konto*>::iterator it;

    ofstream accountFile(nazwaPliku);

    if (!accountFile.is_open()){
        cout << "Nie otwiera sie plik z kontami\n";
        return;
    }

    for (it = konta.begin(); it != konta.end(); it++){
        string accountType = "";
        string accountLogin = "";
        string accountPassword = "";
        string studentGroup = "";
        string teacherAmountOfMaterialsToVerify = "";
        string adminAmountOfMaterialsToAdd = "";
        string index = "";


        if (typeid(**it) == typeid(Student)){
            accountType = "Student";

            accountLogin = (*it)->getLogin();

            accountPassword = (*it)->getHaslo();
            studentGroup = dynamic_cast<Student*> (*it)->getGrupa();
            index = dynamic_cast<Student*> (*it)->getIndeksStudenta();

            accountFile << accountType << "," << accountLogin << "," << accountPassword << "," << studentGroup << "," << index;
            accountFile << "\n";
        }
        else if (typeid(**it) == typeid(Wykladowca)){
            accountType = "Wykladowca";
            accountLogin = (*it)->getLogin();
            accountPassword = (*it)->getHaslo();
            teacherAmountOfMaterialsToVerify = to_string(dynamic_cast<Wykladowca*> (*it)->getLicznikMaterialowDoWeryfikacji());
            index = dynamic_cast<Wykladowca*> (*it)->getIndeksWykladowcy();

            accountFile << accountType << "," << accountLogin << "," << accountPassword << "," << teacherAmountOfMaterialsToVerify << "," << index;
            accountFile << "\n";
        }
        else if (typeid(**it) == typeid(Admin)){
            accountType = "Admin";
            accountLogin = (*it)->getLogin();
            accountPassword = (*it)->getHaslo();
            adminAmountOfMaterialsToAdd = to_string(dynamic_cast<Admin*> (*it)->getLicznikMaterialowDoDodania());

            accountFile << accountType << "," << accountLogin << "," << accountPassword << "," << adminAmountOfMaterialsToAdd;
            accountFile << "\n";
        }
    }

    accountFile.close();

    ofstream subjectFile(nazwaPlikuPrzedmiotow);

    if (!subjectFile.is_open()){
        cout << "Nie otwiera sie plik z przedmiotami\n";
        return;
    }

    vector<Przedmiot*>::iterator pIt;

    for (pIt = przedmioty.begin(); pIt != przedmioty.end(); pIt++){
        string subjectName = "";
        string subjectDescription = "";
        string subjectContact = "";
        string subjectGroup = "";

        subjectName = (*pIt)->getNazwa();
        subjectDescription = (*pIt)->getOpis();
        subjectContact = (*pIt)->getKontakt();
        subjectGroup = (*pIt)->getGrupa();

        subjectFile << subjectName << "," << subjectDescription << "," << subjectContact << "," << subjectGroup;
        subjectFile << ",WYKLADOWCY";

        vector<Konto*>::iterator accIterator;

        for (accIterator = konta.begin(); accIterator != konta.end(); accIterator++){
            if (typeid(**accIterator) == typeid(Wykladowca)){
                if ((*pIt)->getWykladowca((*accIterator)->getLogin()) != nullptr){
                    subjectFile << "," << ((*accIterator)->getLogin());
                }
            }
        }

        subjectFile << ",STUDENCI";

        bool hasStudents = false;

        for (accIterator = konta.begin(); accIterator != konta.end(); accIterator++){
            if (typeid(**accIterator) == typeid(Student)){
                if ((*pIt)->getStudent((*accIterator)->getLogin()) != nullptr){
                    subjectFile << "," << ((*accIterator)->getLogin());
                    hasStudents = true;
                }
            }
        }

        if (!hasStudents){
            subjectFile << ",brak";
        }

        subjectFile << ",MATERIALY";

        int materialSize = (*pIt)->getIloscMaterialow();

        if (materialSize == 0){
            subjectFile << ",brak";
        }
            else {
            for (int i = 0; i < materialSize; i++){
                string currentTitle = "";
                string currentAttachment = "";
                string fromTeacher = "";
                string isVerified = "";
                string isAddedByAdmin = "";

                Material* currentMaterial = (*pIt)->getMaterial(i);

                if (currentMaterial != nullptr){
                    subjectFile << "," << currentMaterial->getTytul() << "," << currentMaterial->getZalacznik();

                    if (currentMaterial->getMaterialOdWykladowcy()){
                        fromTeacher = "true";
                    }
                    else{
                        fromTeacher = "false";
                    }

                    if (currentMaterial->getCzyJestZweryfikowany()){
                        isVerified = "true";
                    }
                    else {
                        isVerified = "false";
                    }

                    if (currentMaterial->getCzyJestDodanyPrzezAdmina()){
                        isAddedByAdmin = "true";
                    }
                    else {
                        isAddedByAdmin = "false";
                    }

                    subjectFile << "," << fromTeacher << "," << isVerified << "," << isAddedByAdmin;

                }
            }
        }
        subjectFile << "\n";
    }
}

bool SystemEdukacyjny::zweryfikujIndeks(string indeks, string typKonta, string nazwaPliku) {
    ifstream file;

    file.open(nazwaPliku, ios::in);

    string line = "";
    string word = "";

    while (getline(file, line)){
        stringstream s(line);
        int counter = 0;

        string currentIndex = "";
        string currentAccountType = "";
        string currentLogin = "";

        while(getline(s, word, ',')){
            counter++;

            if (counter == 1){
                currentIndex = word;
            }
            else if (counter == 2){
                currentAccountType = word;
            }
            else if (counter == 3){
                currentLogin = word;
            }
        }

        if (currentAccountType == typKonta && indeks == currentIndex){
            if (currentLogin == "brak"){
                return true;
            }
            else {
                return false;
            }
        }
    }

    file.close();

    return false;
}


void SystemEdukacyjny::zaktualizujIndeks(string indeks, string login, string nazwaPliku) {
    ifstream in;
    in.open(nazwaPliku, ios::in);

    string line = "";
    string word = "";
    string contents = "";

    while (getline(in, line)){
        stringstream s(line);
        int counter = 0;

        string currentIndex = "";
        string currentAccountType = "";
        string currentLogin = "";

        while (getline(s, word, ',')){
            counter++;

            if (counter == 1){
                currentIndex = word;
            }
            else if (counter == 2){
                currentAccountType = word;
            }
            else if (counter == 3){
                currentLogin = word;
            }
        }

        if (currentIndex == indeks){
            currentLogin = login;
        }

        contents = contents + currentIndex + "," + currentAccountType + "," + currentLogin + "\n";
    }

    in.close();

    ofstream out;
    out.open(nazwaPliku, ios::out | ios::trunc);

    out << contents;

    out.close();
}

void SystemEdukacyjny::przypiszStudentaDoPrzedmiotuPoGrupie(string login) {
    Student* foundStudent = dynamic_cast<Student*> (getKonto(login));
    vector<Przedmiot*>::iterator it;

    for (it = przedmioty.begin(); it != przedmioty.end(); it++){
        if ((*it)->getGrupa() == foundStudent->getGrupa()){
            (*it)->attachStudent(foundStudent);
        }
    }

}

void SystemEdukacyjny::printDataSesja() {
    cout << "Aktywna sesja o adresie ip " << aktywnaSesja->getIpAdres() << ": aktywna liczba prob = " << aktywnaSesja->getProby();

    if (aktywnaSesja->getCzyJestZablokowana()){
        cout << ", zablokowana do " << aktywnaSesja->getZablokowanaDo() << "\n";
    }
    else {
        cout <<", nie jest obecnie zablokowana\n";
    }
}

void SystemEdukacyjny::setDataSesja(string ip, int proby, bool czyJestZablokowana, time_t zablokowanaDo, time_t ostatniaProba) {
    aktywnaSesja->setIpAdres(ip);
    aktywnaSesja->setProby(proby);
    aktywnaSesja->setCzyJestZablokowana(czyJestZablokowana);
    aktywnaSesja->setZablokowanaDo(zablokowanaDo);
    aktywnaSesja->setOstatniaProba(ostatniaProba);
}

void SystemEdukacyjny::wczytajSesje(string nazwaPlikuSesji) {
    ifstream file(nazwaPlikuSesji, ios::in);
    if (!file.is_open()){
        return;
    }

    string line, word;
    while(getline(file, line)){
        stringstream s(line);

        string ip = "";
        string attempts = "";
        string isBlocked = "";
        string blokcedTill = "";
        string lastAttempt = "";

        int counter = 0;

        while (getline(s, word, ',')){
            counter++;

            if (counter == 1){
                ip = word;
            }
            else if (counter == 2){
                attempts = word;
            }
            else if (counter == 3){
                isBlocked = word;
            }
            else if (counter == 4){
                blokcedTill = word;
            }
            else if (counter == 5){
                lastAttempt = word;
            }
        }
        if (ip == aktywnaSesja->getIpAdres()){
            bool isBlockedBool = false;

            if (isBlocked == "false"){
                isBlockedBool = false;
            }
            else if (isBlocked == "true"){
                isBlockedBool = true;
            }

            setDataSesja(ip, stoi(attempts), isBlockedBool, stoll(blokcedTill), stoll(lastAttempt));
            break;
        }
    }
    file.close();
}

void SystemEdukacyjny::zapiszSesje(string nazwaPlikuSesji) {
    ifstream in(nazwaPlikuSesji, ios::in);

    string line = "";
    string contents = "";

    if (in.is_open()){
        while (getline(in, line)){
            stringstream s(line);
            string fileIp;
            getline(s, fileIp, ',');

            if (fileIp != aktywnaSesja->getIpAdres() && !fileIp.empty()){
                contents = contents + line + "\n";
            }
        }
        in.close();
    }

    if (aktywnaSesja->getProby() > 0 || aktywnaSesja->getCzyJestZablokowana()){
        string status = "";

        if (aktywnaSesja->getCzyJestZablokowana()){
            status = "true";
        }
        else if (!aktywnaSesja->getCzyJestZablokowana()){
            status = "false";
        }

        contents = contents + aktywnaSesja->getIpAdres() + ',' + to_string(aktywnaSesja->getProby()) + "," + status + "," + to_string(aktywnaSesja->getZablokowanaDo()) + "," + to_string(aktywnaSesja->getOstatniaProba()) + "\n";
    }

    ofstream out(nazwaPlikuSesji, ios::out | ios::trunc);

    if (out.is_open()){
        out << contents;
        out.close();
    }
}

